    // Pseudocode translated into C++17:
    // 1. Prompt the user to enter the first integer
    // 2. Input the first integer
    // 3. Prompt the user to enter the second integer
    // 4. Input the second integer
    // 5. Add first integer and second integer, store result
    // 6. Display result

    int number1{0};
    int number2{0};

    if (std::cin >> number1 >> number2) {
        const int sum{number1 + number2};
        std::cout << "Sum: " << sum << "\n";
    }

    return 0;
}

#include <iostream>

int main() {
    // Demonstrating the built-in Sequence Structure in C++17
    // Action 1: Initialize accumulator and counter
    int total{0};
    int counter{0};

    int grade1{85};
    int grade2{92};

    // Sequential step 1: add grade to total
    total = total + grade1;
    // Sequential step 2: add 1 to counter
    counter = counter + 1;

    // Sequential step 3: add next grade to total
    total = total + grade2;
    // Sequential step 4: add 1 to counter
    counter = counter + 1;

    std::cout << "Total: " << total << "\n";
    std::cout << "Counter: " << counter << "\n";
    return 0;
}
